// src/pages/customer/SelectDatePage.tsx
import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { useLocation, useNavigate } from "react-router-dom";
import TabBar from "../../components/common/TabBar";
import Button from "../../components/common/Button";
import SecondaryButton from "../../components/common/SecondaryButton";
import api from "../../utils/api";

type ServiceDto = {
  _id: string;
  name: string;
  durationMinutes: number;
  priceBHD: number;
};

type StaffDto = {
  _id: string;
  name: string;
};

type LocationState = {
  isReschedule?: boolean;
  bookingId?: string;
  businessId: string;
  businessName: string;
  selectedServices: ServiceDto[];
  totalDurationMinutes: number;
  totalPrice: number;
};

const PageWrapper = styled.div`
  background-color: #faf6ea;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 900px;
  padding: 40px 0 60px;
  display: flex;
  flex-direction: column;
  gap: 24px;
`;

const Title = styled.h1`
  font-size: 32px;
  font-weight: 800;
  color: #27374d;
`;

const SubTitle = styled.p`
  font-size: 15px;
  color: #555;
`;

const Section = styled.div`
  background: #ffffff;
  border-radius: 12px;
  padding: 20px 24px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
`;

const SectionTitle = styled.h2`
  font-size: 20px;
  font-weight: 700;
  color: #27374d;
  margin-bottom: 12px;
`;

const FormRow = styled.div`
  display: flex;
  gap: 20px;
  align-items: center;
  flex-wrap: wrap;
`;

const Label = styled.label`
  font-size: 14px;
  color: #555;
`;

const DateInput = styled.input`
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid #ddd;
  font-size: 14px;
`;

const SelectInput = styled.select`
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid #ddd;
  font-size: 14px;
  min-width: 160px;
`;

const HelperText = styled.p`
  margin-top: 8px;
  font-size: 13px;
  color: #777;
`;

const ButtonRow = styled.div`
  display: flex;
  gap: 16px;
  margin-top: 20px;
`;

const ErrorText = styled.p`
  color: red;
  margin-top: 8px;
`;

// ===================== COMPONENT =====================

const SelectDatePage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  // Keep location.state in a hook so hooks order is always stable
  const initialState = location.state as LocationState | undefined;
  const [state] = useState<LocationState | undefined>(initialState);

  const [staffList, setStaffList] = useState<StaffDto[]>([]);
  const [selectedStaffId, setSelectedStaffId] = useState<string>("");

  const [selectedDate, setSelectedDate] = useState<string>(() => {
    const today = new Date();
    return today.toISOString().slice(0, 10); // YYYY-MM-DD
  });

  const [availableSlots, setAvailableSlots] = useState<string[]>([]);
  const [selectedSlot, setSelectedSlot] = useState<string>("");

  const [loadingSlots, setLoadingSlots] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // If state is missing / corrupted, kick back to home
  useEffect(() => {
    if (
      !state ||
      !state.businessId ||
      !state.selectedServices ||
      !state.selectedServices.length
    ) {
      navigate("/home");
    }
  }, [state, navigate]);

  // Load staff for this business
  useEffect(() => {
    const fetchStaff = async () => {
      try {
        if (!state?.businessId) return;
        const res = await api.get(`/public/businesses/${state.businessId}`);
        const business = res.data?.business;
        const staff: StaffDto[] = business?.staff || [];
        setStaffList(staff);
      } catch (err) {
        console.error("Error loading staff:", err);
      }
    };

    fetchStaff();
  }, [state?.businessId]);

  // Load available time slots for selected date (business-level)
  useEffect(() => {
    const fetchSlots = async () => {
      if (!state) return;
      const { businessId, totalDurationMinutes } = state;
      if (!businessId || !totalDurationMinutes || !selectedDate) return;

      try {
        setLoadingSlots(true);
        setError(null);

        const res = await api.get<string[]>(
          `/bookings/available-slots/${businessId}`,
          {
            params: {
              date: selectedDate,
              duration: totalDurationMinutes,
            },
          }
        );

        setAvailableSlots(res.data || []);
        setSelectedSlot("");
      } catch (err: any) {
        console.error("Error loading slots", err);
        setError(
          err?.response?.data?.message ||
            "Failed to load available slots. Please try again."
        );
      } finally {
        setLoadingSlots(false);
      }
    };

    if (state) {
      fetchSlots();
    }
  }, [state, selectedDate]);

  const handleNext = () => {
    if (!state) return;

    const {
      businessId,
      businessName,
      selectedServices,
      totalDurationMinutes,
      totalPrice,
      isReschedule,
      bookingId,
    } = state;

    // date & time first
    if (!selectedDate || !selectedSlot) {
      setError("Please select a date and time.");
      return;
    }

    // then staff
    if (staffList.length > 0 && !selectedStaffId) {
      setError("Please select a staff member.");
      return;
    }

    setError(null);

    const selectedStaff =
      staffList.find((s) => s._id === selectedStaffId) || null;

    navigate("/book/summary", {
      state: {
        businessId,
        businessName,
        selectedServices,
        totalDurationMinutes,
        totalPrice,
        date: selectedDate,
        time: selectedSlot,
        isReschedule,
        bookingId,
        // pass staff to summary
        staffId: selectedStaffId || undefined,
        staffName: selectedStaff ? selectedStaff.name : undefined,
      },
    });
  };

  // Guard render in case state is missing
  if (
    !state ||
    !state.businessId ||
    !state.selectedServices ||
    !state.selectedServices.length
  ) {
    return null;
  }

  const {
    businessName,
    selectedServices,
    totalDurationMinutes,
    totalPrice,
    isReschedule,
  } = state;

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        <div>
          <Title>{businessName}</Title>
          <SubTitle>
            Select <strong>date and time</strong>, then choose a{" "}
            <strong>staff member</strong> for your{" "}
            {selectedServices.map((s) => s.name).join(", ")} (
            {totalDurationMinutes} mins · {totalPrice.toFixed(2)} BHD)
          </SubTitle>
        </div>

        <Section>
          <SectionTitle>Date, Time & Staff</SectionTitle>

          <FormRow style={{ marginBottom: 16 }}>
            {/* 1) DATE */}
            <Label>
              Date
              <br />
              <DateInput
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
              />
            </Label>

            {/* 2) TIME */}
            <Label>
              Time
              <br />
              <SelectInput
                value={selectedSlot}
                onChange={(e) => setSelectedSlot(e.target.value)}
                disabled={loadingSlots || availableSlots.length === 0}
              >
                <option value="">
                  {loadingSlots
                    ? "Loading..."
                    : availableSlots.length === 0
                    ? "No slots available"
                    : "Select time"}
                </option>
                {availableSlots.map((slot) => (
                  <option key={slot} value={slot}>
                    {slot}
                  </option>
                ))}
              </SelectInput>
            </Label>

            {/* 3) STAFF (after date+time) */}
            {staffList.length > 0 && (
              <Label>
                Staff
                <br />
                <SelectInput
                  value={selectedStaffId}
                  onChange={(e) => setSelectedStaffId(e.target.value)}
                >
                  <option value="">Select staff</option>
                  {staffList.map((staff) => (
                    <option key={staff._id} value={staff._id}>
                      {staff.name}
                    </option>
                  ))}
                </SelectInput>
              </Label>
            )}
          </FormRow>

          <HelperText>
            Time options follow the salon&apos;s working hours for the selected
            day. After you pick a date and time, choose which staff member you
            want for this appointment.
          </HelperText>

          {error && <ErrorText>{error}</ErrorText>}

          <ButtonRow>
            <SecondaryButton width="160px" onClick={() => navigate(-1)}>
              Back
            </SecondaryButton>
            <Button width="220px" onClick={handleNext}>
              {isReschedule ? "Review Changes" : "Review Booking"}
            </Button>
          </ButtonRow>
        </Section>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default SelectDatePage;
